old:
    const pusher = new Pusher(env.NEXT_PUBLIC_PUSHER_KEY, {
      cluster: env.NEXT_PUBLIC_PUSHER_CLUSTER,
    });

    const channel = pusher.subscribe(genMessageChannelKey(messageRef.current.id));
    channel.bind('message-update', (hash: unknown) => {
      if (!messageRef.current) return;
      const ownSaveIndex = ownSaveRecordsRef.current
        .findIndex((record) => record === hash);
      if (ownSaveIndex >= 0) ownSaveRecordsRef.current.splice(ownSaveIndex, 1);
      const shownHash = hashMessage(normalizeForHash(messageRef.current));
      if (ownSaveIndex < 0 && hash !== shownHash) {
        showConfirmation({
          enabled: true,
          title: 'Message Update Detected',
          confirmText: 'Reload',
          onConfirm: reloadMessage,
          message: `The message you are viewing has been updated. Would you like to reload it?${hasChangedRef.current ? ' Any changes you have made will be lost.' : ''}`,
        });
      }
    });

    return () => {
      channel.unbind();
      pusher.unsubscribe(genMessageChannelKey(id));
      pusher.disconnect();
    };
  }, [messageRef.current && isApiMessage(messageRef.current) && messageRef.current.id]);
};

